// node1 - actuator node

#include <stdint.h>
#include "brake.h"
#include "fan.h"
#include "can.h"

#define HCLK_HZ 16000000U

static volatile uint32_t system_ms = 0U;

void SysTick_Handler(void)
{
    system_ms++;
}

static void systick_init(void)
{
    // SysTick CTRL
    // Disable SysTick
    *(volatile uint32_t*) 0xE000E010U = 0U;

    // SysTick LOAD
    // 1ms period
    *(volatile uint32_t*) 0xE000E014U =
        (HCLK_HZ / 1000U) - 1U;

    // SysTick VAL
    // Clear current value
    *(volatile uint32_t*) 0xE000E018U = 0U;

    // SysTick CTRL
    // ENABLE = 1
    // TICKINT = 1
    // CLKSOURCE = 1 (HCLK)
    *(volatile uint32_t*) 0xE000E010U = 0b111U;
}

int main(void)
{
    set_brake();
    set_fan();
    can1_init();
    systick_init();

    while(1)
    {
        uint32_t now_ms = system_ms;

        node1_receive_command(now_ms);

        can_poll_tx_result();

        can_poll_error_status();

        can_handle_error();

        node1_check_brake_timeout(now_ms);
    }
}